<link rel="stylesheet" href="<?=asset('css/publishing.css')?>">
<main class="write-main pub-main">
  <div class="writer-head"><div><span class="writer-kicker">Prepare · Review · Release</span><h1><?=$package?'Publication package':'Prepare a publication'?></h1><p class="pub-lead">One article, with a considered version for each audience. Save your draft before reviewing the exact content to approve.</p></div><a class="wbtn" href="<?=url('/write/publishing')?>">All packages</a></div>
  <nav class="pub-nav" aria-label="Package sections"><a href="#draft">Edit draft</a><?php if($package):?><a href="#review">Saved review</a><a href="#deliveries">Delivery records</a><?php endif;?><a href="<?=url('/write/connections')?>">Connections</a></nav>
  <?php foreach(flashes() as $f):?><div class="notice <?=$f['type']==='error'?'error':''?>"><?=e($f['message'])?></div><?php endforeach;?>
  <form id="draft" method="post" action="<?=url('/write/publishing/save')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=intval($package['id']??0)?>"><input type="hidden" name="draft_version" value="<?=intval($package['draft_version']??0)?>"><input type="hidden" name="source_post_id" value="<?=intval($draft['source_post_id']??0)?>">
    <section class="pub-card"><span class="writer-kicker">Draft <?=$package?'version '.intval($package['draft_version']):''?></span><div class="field"><label for="package-title">Package title</label><input class="pub-editor-title" id="package-title" name="title" required maxlength="240" value="<?=e($draft['title'])?>" placeholder="Week 1 — The problem we are testing"></div><div class="field"><label for="source-url">Public article URL</label><input id="source-url" type="url" name="source_url" value="<?=e($draft['source_url'])?>" placeholder="https://www.waithakandegwa.com/my-thoughts/…"><span class="pub-input-note">Include this link in the captions where it helps the reader. The centre does not silently append it.</span></div><details><summary class="pub-help">Private production notes</summary><div class="field"><label for="package-notes">Notes, context and consent references</label><textarea id="package-notes" name="notes" maxlength="5000"><?=e($draft['notes']??'')?></textarea><small>These notes stay in Writer and are never sent to a social provider.</small></div></details></section>
    <section class="pub-section"><h2 class="pub-section-title">Channel versions</h2><p>Select the channels for this release. Media must already be approved for public delivery and remain accessible through the publication time. Use a distinct file URL for every approved asset; replacing the file at the same URL would change what is sent.</p><div class="pub-grid">
    <?php foreach($channels as $channel):$slug=$channel['slug'];$v=$draft['variants'][$slug];$formats=in_array($slug,['instagram','facebook'],true)?['post'=>'Post','reel'=>'Reel','story'=>'Story']:($slug==='youtube'?['short'=>'Short']:['post'=>'Post']);?>
      <section class="pub-card"><label class="pub-choice"><input type="checkbox" name="variants[<?=e($slug)?>][enabled]" value="1" <?=$v['enabled']?'checked':''?>><span><strong><?=e($channel['name'])?></strong><small><?=e(ucfirst($channel['delivery_method']))?> delivery · <?=e(str_replace('_',' ',$channel['account_type']))?></small></span></label>
        <div class="field"><label for="text-<?=e($slug)?>">Caption / post text</label><textarea class="pub-caption" id="text-<?=e($slug)?>" name="variants[<?=e($slug)?>][text]" maxlength="20000"><?=e($v['text'])?></textarea></div>
        <div class="pub-inline-fields"><div class="field"><label for="format-<?=e($slug)?>">Format</label><select id="format-<?=e($slug)?>" name="variants[<?=e($slug)?>][format]"><?php foreach($formats as $key=>$name):?><option value="<?=e($key)?>" <?=$v['format']===$key?'selected':''?>><?=e($name)?></option><?php endforeach;?></select></div><div class="field"><label for="media-type-<?=e($slug)?>">Media type</label><select id="media-type-<?=e($slug)?>" name="variants[<?=e($slug)?>][media_type]"><option value="image" <?=$v['media_type']==='image'?'selected':''?>>Image</option><option value="video" <?=$v['media_type']==='video'?'selected':''?>>Video</option></select></div></div>
        <div class="field"><label for="media-url-<?=e($slug)?>">Public media file URL, if used</label><input type="url" id="media-url-<?=e($slug)?>" name="variants[<?=e($slug)?>][media_url]" value="<?=e($v['media_url'])?>" placeholder="https://…/approved-image.jpg"><small>One image or video in this release. A video-platform watch link is not a video file. Use the approved public media host.</small></div>
        <div class="field"><label for="alt-<?=e($slug)?>">Image description</label><input id="alt-<?=e($slug)?>" name="variants[<?=e($slug)?>][alt_text]" maxlength="1000" value="<?=e($v['alt_text'])?>"><small>Used where the destination accepts alt text; retained for assisted posting everywhere.</small></div>
        <?php if($slug==='youtube'):?><div class="field"><label for="youtube-title">Video title</label><input id="youtube-title" name="variants[youtube][title]" value="<?=e($v['title'])?>" maxlength="100"></div><div class="field"><label for="youtube-privacy">Video visibility</label><select id="youtube-privacy" name="variants[youtube][privacy]"><?php foreach(['private'=>'Private','unlisted'=>'Unlisted','public'=>'Public'] as $key=>$label):?><option value="<?=e($key)?>" <?=$v['privacy']===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select><small>This choice is included in the approved revision. YouTube determines whether a video qualifies as a Short; review its format and length before approval.</small></div><label class="pub-choice"><input type="checkbox" name="variants[youtube][made_for_kids]" value="1" <?=$v['made_for_kids']?'checked':''?>><span>This video is made for children.</span></label><?php endif;?>
        <?php if(in_array($slug,['youtube','instagram','tiktok'],true)):?><label class="pub-choice"><input type="checkbox" name="variants[<?=e($slug)?>][ai_generated]" value="1" <?=$v['ai_generated']?'checked':''?>><span>Apply this platform’s AI-generated-content disclosure.</span></label><?php endif;?>
      </section>
    <?php endforeach;?></div></section>
    <div class="pub-save-bar"><p>Saving edits creates a new draft version. Approved revisions and existing delivery jobs retain their exact content.</p><button class="wbtn primary" type="submit">Save draft</button></div>
  </form>
  <?php if($package):?>
  <section class="pub-section pub-connection-anchor" id="review"><h2 class="pub-section-title">Review the saved version</h2><p>These previews reflect saved draft version <?=intval($package['draft_version'])?>. Changes still in the form above must be saved before they can be approved.</p>
    <div class="pub-grid">
    <?php $selected=0;$reviewDestinations=[];$frozenApproval=$revision?publishing_decode($revision['snapshot_json']):null;foreach($channels as $channel):$slug=$channel['slug'];$v=$draft['variants'][$slug];if(!$v['enabled'])continue;$selected++;$destination=null;$gate=null;try{$destination=$frozenApproval['destinations'][$slug]??publishing_destination($channel,$v);$reviewDestinations[$slug]=$destination;publishing_validate_variant($slug,$v,$destination);}catch(Throwable $e){$gate=$e->getMessage();}?>
      <article class="pub-card"><div class="pub-card-top"><h3><?=e($channel['name'])?></h3><span class="pub-status <?=$gate?'failed':'connected'?>"><?=$gate?'Needs a step':'Ready to review'?></span></div>
        <?php if($gate):?><div class="pub-hint pub-warning"><?=e($gate)?></div><?php endif;?>
        <p class="pub-review-meta"><?=e($destination['account_name']??$channel['profile_url'])?><br><?=e(ucfirst($destination['method']??$channel['delivery_method']))?> · <?=e(ucfirst($v['format']))?><?=$slug==='youtube'?' · '.e(ucfirst($v['privacy'])):''?></p>
        <?php if($slug==='youtube'):?><h3><?=e($v['title'])?></h3><?php endif;?>
        <div class="pub-review-copy"><?=e($v['text'])?></div>
        <?php if($v['media_url']):?><p><a class="pub-media-link" href="<?=e($v['media_url'])?>" target="_blank" rel="noopener noreferrer">Review <?=e($v['media_type'])?> file ↗</a></p><p class="pub-review-meta">Image description: <?=e($v['alt_text']?:'Not supplied')?></p><?php endif;?>
        <?php if($v['ai_generated']):?><p class="pub-review-meta">AI-generated-content disclosure selected.</p><?php endif;?>
      </article>
    <?php endforeach;?></div>
    <?php if(!$selected):?><div class="pub-hint">Select at least one channel above and save the draft to build a reviewable package.</div><?php endif;?>
    <?php if(!$revision):?><form class="pub-card pub-section" method="post" action="<?=url('/write/publishing/'.$package['id'].'/approve')?>"><?=csrf_field()?><input type="hidden" name="draft_version" value="<?=intval($package['draft_version'])?>"><input type="hidden" name="destinations_hash" value="<?=e(hash('sha256',publishing_json($reviewDestinations)))?>"><h3>Approve this saved revision</h3><label class="pub-choice"><input type="checkbox" name="approve_content" value="1" required><span>I reviewed the saved text, media, visibility and actual destinations above.</span></label><label class="pub-choice"><input type="checkbox" name="media_rights" value="1" required><span>I have the necessary permission for these quotations, images, video and audio, including any people featured.</span></label><button type="submit" class="wbtn primary" <?=$selected?'':'disabled'?>>Approve saved revision</button></form>
    <?php else:$approved=publishing_decode($revision['snapshot_json']);?><div class="pub-card pub-section"><span class="pub-status connected">Revision <?=intval($revision['draft_version'])?> approved</span><p>Approved <?=e(publishing_local_time($revision['approved_at']))?>. This immutable revision contains <?=count($approved['destinations'])?> destination<?=count($approved['destinations'])===1?'':'s'?>.</p><form method="post" action="<?=url('/write/publishing/'.$package['id'].'/schedule')?>"><?=csrf_field()?><input type="hidden" name="revision_id" value="<?=intval($revision['id'])?>"><div class="field"><label for="release-time">Release time · <?=e((string)app_config('timezone','Africa/Nairobi'))?></label><input id="release-time" type="datetime-local" name="scheduled_at" required value="<?=e((new DateTimeImmutable('now',new DateTimeZone((string)app_config('timezone','Africa/Nairobi'))))->modify('+1 hour')->format('Y-m-d\TH:i'))?>"></div><p class="pub-help">The worker sends the approved jobs at this time. Assisted channels become tasks. Scheduling the same revision again will not create duplicate jobs.</p><button class="wbtn primary" type="submit">Schedule approved revision</button></form></div><?php endif;?>
  </section>
  <section class="pub-section pub-connection-anchor" id="deliveries"><h2 class="pub-section-title">Delivery records</h2><div class="pub-card">
    <?php if(!$jobs):?><p>No delivery jobs yet. Approve the saved package and choose its release time.</p><?php endif;?>
    <?php foreach($jobs as $job):$destination=publishing_decode($job['destination_json']);?>
    <article class="pub-job"><div class="pub-job-head"><div><h3><?=e($job['channel_name'])?> · revision <?=intval($job['draft_version'])?></h3><span class="pub-help"><?=e(publishing_local_time($job['scheduled_at']))?></span></div><span class="pub-status <?=e($job['status'])?>"><?=e(publishing_job_label($job))?></span></div>
      <p class="pub-review-meta"><?=e($destination['account_name']??$destination['profile_url'])?> · <?=e($job['method'])?></p>
      <?php if($job['last_error']):?><div class="pub-hint pub-warning"><?=e($job['last_error'])?></div><?php endif;?>
      <div class="pub-actions"><?php if($job['external_url']&&publishing_public_url($job['external_url'])):?><a class="wbtn" target="_blank" rel="noopener noreferrer" href="<?=e($job['external_url'])?>">View post ↗</a><?php endif;?><a class="wbtn" target="_blank" rel="noopener noreferrer" href="<?=e($destination['profile_url'])?>">Open platform ↗</a><?php if($job['method']==='buffer'&&$job['remote_id']):?><a class="wbtn" target="_blank" rel="noopener noreferrer" href="https://publish.buffer.com/">Open Buffer ↗</a><?php endif;?></div>
      <?php if(in_array($job['status'],['assisted','reminder_queued','reminder_sent','ambiguous','failed','reconnect','delivered'],true)):?>
        <details><summary>Approved content & completion</summary>
        <?php $st=db()->prepare('SELECT snapshot_json FROM publishing_revisions WHERE id=?');$st->execute([$job['revision_id']]);$frozen=publishing_decode((string)$st->fetchColumn());$variant=$frozen['variants'][$destination['slug']];?>
        <div class="field"><label for="copy-<?=intval($job['id'])?>">Approved text to copy</label><textarea id="copy-<?=intval($job['id'])?>" readonly><?=e($variant['text'])?></textarea></div>
        <?php if($variant['media_url']):?><p><a href="<?=e($variant['media_url'])?>" target="_blank" rel="noopener noreferrer">Open approved media ↗</a></p><?php endif;?>
        <form method="post" action="<?=url('/write/publishing/jobs/'.$job['id'].'/complete')?>"><?=csrf_field()?><div class="field"><label for="published-<?=intval($job['id'])?>">Actual published post URL</label><input type="url" required id="published-<?=intval($job['id'])?>" name="external_url" placeholder="Paste the platform’s link to this post"></div><label class="pub-choice"><input required type="checkbox" name="confirm_published" value="1"><span>This exact post or upload is complete, with the approved visibility. I checked that no duplicate is still waiting in the provider queue.</span></label><button class="wbtn" type="submit">Record published link</button></form>
        </details>
      <?php endif;?>
      <?php if(in_array($job['status'],['failed','reconnect'],true)):?><details><summary>Review a failed delivery</summary><form method="post" action="<?=url('/write/publishing/jobs/'.$job['id'].'/retry')?>"><?=csrf_field()?><label class="pub-choice"><input type="checkbox" name="reviewed_remote" value="1" required><span>I reviewed the existing provider record and resolved the reported problem. Resume this job, using its existing provider post when one exists.</span></label><button class="wbtn" type="submit">Resume reviewed job</button></form></details><?php endif;?>
      <?php if(in_array($job['status'],['scheduled','assisted','failed','reconnect','ambiguous','reminder_queued','reminder_sent'],true)):?><details><summary>Cancel or close this record</summary><form method="post" action="<?=url('/write/publishing/jobs/'.$job['id'].'/cancel')?>"><?=csrf_field()?><?php if($job['remote_id']||$job['status']==='ambiguous'):?><label class="pub-choice"><input required type="checkbox" name="reviewed_remote" value="1"><span>I have checked and stopped any pending work in the provider. Closing this local record will not cancel a remote post.</span></label><?php endif;?><button class="pub-muted-button" type="submit">Cancel local job</button></form></details><?php endif;?>
    </article><?php endforeach;?>
  </div></section>
  <?php if($events):?><details class="pub-details"><summary>Publication history</summary><div><ol class="pub-timeline"><?php foreach($events as $event):?><li><strong><?=e(ucfirst(str_replace('_',' ',$event['event_type'])))?></strong><p><?=e($event['note'])?></p><time><?=e(format_date($event['created_at']))?></time></li><?php endforeach;?></ol></div></details><?php endif;?>
  <?php endif;?>
</main>
